    (hg : q ∈ Obstruction.fiberPiece k n) : q = 0

theorem derivation_iterate_eq_zero_of_le (D : Derivation k A A) {a : A} {m n : ℕ}
    (hm : (D : A → A)^[m] a = 0) (hmn : m ≤ n) :
    (D : A → A)^[n] a = 0

theorem exists_last_nonzero_iterate (D : Derivation k A A) {a : A}
    (ha : a ≠ 0) (hnil : ∃ n : ℕ, (D : A → A)^[n] a = 0) :
    ∃ m : ℕ, (D : A → A)^[m] a ≠ 0 ∧ (D : A → A)^[m + 1] a = 0

theorem exists_base_of_constant_charts {q : C k}
    {v : BaseAway k 0} {w : BaseAway k 1}
    (hA : chartMapA k q = Polynomial.C v)
    (hD : chartMapD k q = Polynomial.C w) :
    ∃ r : Base k, baseMap r = q

theorem degreeLE_iterate (D : A →ₗ[k] A) {m i : ℤ}
    (hD : HasShiftLE 𝒜 D m) {x : A} (hx : x ∈ 𝒜 i) (n : ℕ) :
    DegreeLE 𝒜 (i + (n : ℤ) * m) ((D : A → A)^[n] x)

theorem degreeLE_map (D : A →ₗ[k] A) {m d : ℤ}
    (hD : HasShiftLE 𝒜 D m) {x : A} (hx : DegreeLE 𝒜 d x) :
    DegreeLE 𝒜 (d + m) (D x)

theorem le_of_proj_ne_zero_of_degreeLE {d : ℤ} {x : A}
    (hx : DegreeLE 𝒜 d x) {i : ℤ}
    (hi : proj 𝒜 i x ≠ 0) : i ≤ d

theorem top_projection_map (D : A →ₗ[k] A) {m d : ℤ}
    (hD : HasShiftLE 𝒜 D m) {x : A} (hx : DegreeLE 𝒜 d x) :
    proj 𝒜 (d + m) (D x) = componentLinear 𝒜 D m (proj 𝒜 d x)

theorem degree_eq_of_least {A : Type*} (F : ℤ → Set A) {x : A} {d : ℤ}
    (hd : x ∈ F d) (hleast : ∀ e : ℤ, x ∈ F e → d ≤ e) :
    degree F x = d

theorem determinant_algHom_ext_frame {φ ψ : Obstruction.C k →ₐ[k] S}
    (hF : frameOfHom φ = frameOfHom ψ)
    (hu : φ (Obstruction.cX k 4) = ψ (Obstruction.cX k 4)) : φ = ψ

theorem mk_mem_gPiece {n : ℤ} {q : P k 5}
    (hq : q.IsWeightedHomogeneous presentationWeight n) :
    Ideal.Quotient.mk (idealG k) q ∈ gPiece k n

theorem descend_invariant (D : Derivation k A[T;T⁻¹] A[T;T⁻¹]) (q : ℤ)
    (hq : HomogeneousOnConstants D q) (hT : D (T 1) = 0) {a : A} {j : ℤ}
    (ha : D (C a * T j) = 0) : descend D q hq a = 0

theorem coefficient_mem_power {I : Ideal R} {p : R[T;T⁻¹]}
    (hp : p ∈ modification I) (ℓ : ℕ) :
    p.coeff (-(ℓ : ℤ)) ∈ I ^ ℓ

theorem eq_single_of_homogeneous {ℓ : ℤ} {p : R[T;T⁻¹]}
    (hp : Homogeneous ℓ p) :
    p = AddMonoidAlgebra.single (-ℓ) (p.coeff (-ℓ))

theorem homogeneous_nonzero_numerator {I : Ideal R} {ℓ : ℕ} {p : R[T;T⁻¹]}
    (hp : p ∈ modification I) (hh : Homogeneous (ℓ : ℤ) p) (hne : p ≠ 0) :
    ∃ r ∈ I ^ ℓ, r ≠ 0 ∧ p = C r * T (-(ℓ : ℤ))

theorem homogeneous_numerator {I : Ideal R} {ℓ : ℕ} {p : R[T;T⁻¹]}
    (hp : p ∈ modification I) (hh : Homogeneous (ℓ : ℤ) p) :
    ∃ r ∈ I ^ ℓ, p = C r * T (-(ℓ : ℤ))

theorem negative_single_mem_modification {I : Ideal R} {n : ℕ} {r : R}
    (hr : r ∈ I ^ n) :
    AddMonoidAlgebra.single (-(n : ℤ)) r ∈ modification I

theorem single_mem_modification_of_mem_power {I : Ideal R} (n : ℤ) {r : R}
    (hr : r ∈ I ^ (-n).toNat) :
    AddMonoidAlgebra.single n r ∈ modification I

theorem polynomialMap_homogeneous {p : P k 5} {d : ℤ}
    (hp : p.IsWeightedHomogeneous presentationWeight d) :
    ModificationPieces.Homogeneous d (polynomialMap k p)

theorem polynomialMap_positive_piece {p : P k 5} {ℓ : ℕ}
    (hp : p.IsWeightedHomogeneous presentationWeight (ℓ : ℤ)) :
    ∃ h ∈ I k ^ ℓ, polynomialMap k p = LP.C h * LP.T (-(ℓ : ℤ))

theorem eq_zero_of_homogeneous_negative {w : σ → ℤ} (hw : ∀ i, 0 ≤ w i)
    {p : MvPolynomial σ K} {n : ℤ}
    (hn : p.IsWeightedHomogeneous w n) (hneg : n < 0) : p = 0

theorem homogeneous_weight_nonneg {w : σ → ℤ} (hw : ∀ i, 0 ≤ w i)
    {p : MvPolynomial σ K} (hp : p ≠ 0) {n : ℤ}
    (hn : p.IsWeightedHomogeneous w n) : 0 ≤ n

theorem rigidity_polynomial_weight_neg_two {K : Type*} [CommSemiring K]
    {q : MvPolynomial (Fin 3) K}
    (hq : q.IsWeightedHomogeneous rigidityPolynomialWeight (-2)) : q = 0

theorem toLaurentBase_coeff_eq_zero {r : G k} {n : ℤ}
    (hr : r ∈ gPiece k n) (j : ℤ) (hj : j ≠ -n) :
    (LaurentPresentation.toLaurentBase k r).coeff j = 0

theorem polynomial_units_eq_of_eval_eq {p q : MvPolynomial σ R}
    (hp : IsUnit p) (hq : IsUnit q) (x : σ → R)
    (h : eval x p = eval x q) : p = q

theorem zeroLocus_fiber_ideal (p : MvPolynomial σ k) (t : k) :
    zeroLocus k (Ideal.span ({p - C t} : Set (MvPolynomial σ k))) =
      {x : σ → k | aeval x p = t}

lemma after_send_eq_of_send_pair_eq {P : Law α} {Q : Law η}
    {X : α → β} {W : α → γ} {Y : η → β} {V : η → γ}
    (h : P.send (fun a => (X a, W a)) = Q.send (fun a => (Y a, V a)))
    (w : γ) :
    (P.after W w).send X = (Q.after V w).send Y

lemma crossE_pack {P : Law (ι → α)} {Q : ι → Law α}
    (h : P.dominated (pack Q)) :
    P.crossE (pack Q) = ∑ i, (P.send (fun x => x i)).crossE (Q i)

lemma ext_by_products {P Q : Law (ι → α)}
    (h : ∀ f : ι → α → ℝ, P.Ex (fun x => ∏ i, f i (x i)) = Q.Ex fun x => ∏ i, f i (x i)) :
    P = Q

lemma bill_split (tag : α → G) (c : G → ℝ) (q : Law α)
    (P : Law Ω) (X : Ω → ι → α) (U : Ω → G) (h : covered P X q) (e : τ ⊕ κ ≃ ι) :
    let V := keep X (fun i => e (.inl i))
    let W := keep X (fun i => e (.inr i))
    (P.send W).Ex (fun w => bill tag c q (P.after W w) V U) ≤ bill tag c q P X U

lemma cell_unique (a s : ℝ) (hs : 0 < s) (n : ℕ) {k l : ℕ} {x : ℝ}
    (hx : x ∈ box (lft a s n k) (s*side n))
    (hy : x ∈ box (lft a s n l) (s*side n)) : k = l
